\begin{equation}
 \rho_V=\frac{\mu^4}{4\lambda},
 \qquad
 m=\alpha\mu,
 \qquad
 \beta=\frac{\nu}{\mu^2},
 \qquad
 r_D=\frac{\rho_{D0}}{\rho_V}.
 \label{eq:scw-additive-definitions}
